+  if (b === "timeout-closed") fail("timeout", 124);
+  save(); process.exit(0);
+}
+if (cmd === "pr list") {
+  const st = get("--state", "-s");
+  if (st !== undefined && !["open", "closed", "merged", "all"].includes(st)) invalid("bad state " + st);
+  const fields = checkJson(get("--json"), PR_FIELDS);
